public sealed class MemorySource : IJobSource
{
    private OSJobStatus _status = new() { State = OSJobState.Idle };

    public Task<ApiResult<OSJobStatus>> StatusAsync(CancellationToken token = default) => Reply(_status);

    public Task<ApiResult<TPlan>> PlanAsync<TPlan>(CancellationToken token = default) =>
        Task.FromResult(new ApiResult<TPlan>
        {
            Succeed = true,
            Data = JsonSerializer.Deserialize<TPlan>("""{ "Rows": 120 }""")
        });

    public Task<ApiResult<OSJobStatus>> StartAsync(CancellationToken token = default)
    {
        _status = new OSJobStatus { State = OSJobState.Running, Total = 120 };

        return Reply(_status);
    }

    public Task<ApiResult<OSJobStatus>> StopAsync(CancellationToken token = default)
    {
        _status.State = OSJobState.Cancelled;

        return Reply(_status);
    }

    private static Task<ApiResult<OSJobStatus>> Reply(OSJobStatus status) =>
        Task.FromResult(new ApiResult<OSJobStatus> { Succeed = true, Data = status });
}

